<template>
  <LearnecAppShell role="STUDENT"><section class="assignment-center" data-assignment-center><header><div><p>学生端 / 作业中心</p><h1>我的实训工单</h1><span>查看教师下发的工单，按状态继续实训。</span></div><strong>{{ assignments.length }} 个工单</strong></header><nav class="filters" aria-label="作业状态筛选"><NuxtLink v-for="item in filters" :key="item.value" :to="item.value ? `/center/assignments?status=${item.value}` : '/center/assignments'" :class="{active:currentStatus===item.value}">{{ item.label }}</NuxtLink></nav><div v-if="pending" class="state">正在读取作业...</div><div v-else-if="error" class="state error">作业读取失败，请刷新后重试。</div><div v-else-if="!assignments.length" class="state">当前筛选条件下暂无工单。</div><div v-else class="assignment-grid"><CenterAssignmentCard v-for="assignment in assignments" :key="assignment.id" :assignment="assignment" /></div></section></LearnecAppShell>
</template>
<script setup lang="ts">type Assignment={id:string;title:string;description:string;status:string;autoScoreWeight:number;manualScoreWeight:number;dueAt:string|null}; const route=useRoute(); const currentStatus=computed(()=>typeof route.query.status==='string'?route.query.status:''); const filters=[{label:'全部',value:''},{label:'待开始',value:'AVAILABLE'},{label:'进行中',value:'IN_PROGRESS'},{label:'已提交',value:'SUBMITTED'},{label:'待重做',value:'RETURNED'},{label:'已批阅',value:'GRADED'}]; const url=computed(()=>`/api/center/assignments${currentStatus.value?`?status=${encodeURIComponent(currentStatus.value)}`:''}`); const {data,pending,error}=await useFetch<{assignments:Assignment[]}>(url,{headers:import.meta.server?useRequestHeaders(['cookie']):undefined,watch:[currentStatus]}); const assignments=computed(()=>data.value?.assignments??[])</script>
<style scoped>.assignment-center>header{display:flex;justify-content:space-between;align-items:flex-end;gap:18px;margin-bottom:24px}.assignment-center header p{margin:0;color:#1677ff;font-size:13px;font-weight:800}.assignment-center h1{margin:8px 0 6px;color:#172033;font-size:28px}.assignment-center header span{color:#667085;font-size:14px}.assignment-center header>strong{color:#475467;font-size:13px;white-space:nowrap}.filters{display:flex;gap:6px;overflow-x:auto;margin-bottom:18px;padding-bottom:2px}.filters a{flex:none;padding:8px 13px;border:1px solid #e4e8ef;border-radius:6px;background:#fff;color:#667085;font-size:13px;text-decoration:none}.filters a.active{border-color:#1677ff;background:#eff8ff;color:#145bc2;font-weight:700}.assignment-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.state{padding:44px;border:1px dashed #cbd5e1;border-radius:8px;background:#fff;color:#667085;text-align:center}.state.error{color:#b42318}@media(max-width:980px){.assignment-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:640px){.assignment-center>header{align-items:flex-start;flex-direction:column}.assignment-grid{grid-template-columns:1fr}}</style>
